-- 023: the General Secretary of the Executive Committee, with photograph and biography.
-- Only fills the position while it is still empty, so later edits in the admin are never overwritten.

UPDATE leaders SET
  name = 'Dr. Jerry Bagaya',
  photo = 'assets/img/general-secretary-bagaya.webp',
  bio = 'Dr. Jerry Bagaya is the General Secretary of the Gulu University Convocation (GUCO) and the Academic Registrar of Gulu University. A teacher by profession, he is an experienced educator, administrator and researcher in the field of quality assurance.\n\nHe holds a PhD in Education from Makerere University, a Master of Education in Educational Planning, Management and Administration from Gulu University, and a Bachelor of Science with Education from Makerere University.\n\nDr. Bagaya previously worked as a graduate teacher of Mathematics and Physics at Masindi Academy and Kabalega Secondary School for eight years, as Senior Inspector of Schools (Mathematics and Computer Studies) with the Directorate of Education Standards at the Ministry of Education and Sports for eight years, as a part-time lecturer at Gulu University for four years, and as Assistant Academic Registrar at Kyambogo University for four years. He joined Gulu University in 2016 as Deputy Academic Registrar and was appointed Academic Registrar in 2018, the position he holds to date.\n\nWith over 27 years of experience in teaching, management, supervision and research at all levels of the education system, he is passionate about teaching and about providing opportunities, through servant leadership, for all learners to achieve their full potential. He is enthusiastic, self-motivated, dedicated, organised, reliable and hard-working, with a proven track record in education leadership and management, and is keen to keep learning and developing new skills.'
WHERE organ = 'executive' AND title LIKE 'General Secretary%' AND (name IS NULL OR name = '');
